package main

import (
	"bufio"
	"fmt"
	"os"
)

const (
	K   = 1010
	MOD = 1000000007
)

func powmod(a, x int64) int64 {
	if x == 0 {
		return 1
	}
	if x%2 == 0 {
		return powmod(a*a%MOD, x/2)
	}
	return a * powmod(a, x-1) % MOD
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var k, va, vb int
	fmt.Fscan(in, &k, &va, &vb)

	den := powmod(int64(va+vb), MOD-2)
	pa := int64(va) * den % MOD
	pb := int64(vb) * den % MOD
	oneB := pa * powmod(pb, MOD-2) % MOD

	dp := make([][]int64, K)
	for i := range dp {
		dp[i] = make([]int64, K)
	}

	for i := k - 1; i >= 0; i-- {
		for j := k; j >= 1; j-- {
			if i+j >= k {
				dp[i][j] = (int64(i+j) + oneB) % MOD
			} else {
				dp[i][j] = (pa*dp[i][j+1] + pb*dp[i+j][j]) % MOD
			}
		}
	}

	fmt.Fprintln(out, dp[0][1])
}

